const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
let pequenos = 0;
let medios = 0;

for (let i = 1; i <= n; i++) {
  if (input[i] === 1) pequenos++;
  else medios++;
}

const p = input[n + 1];
const m = input[n + 2];

console.log(pequenos <= p && medios <= m ? 'S' : 'N');
